-- ============================================================================
--  016 - league history: the record book
--
--  Run after 015. Additive and idempotent.
--
--  The 21 leaderboards from the Cool Clan record book, as one 'records' row in
--  league_history. Same table, same policies, same once-a-season SQL paste as
--  013 - this only adds a payload.
--
--  Shape:
--    { team:   { season: [table], game: [table] },
--      player: { season: [table], game: [table] } }
--
--    table = { id, title, wide?, note?, cols: [string],
--              rows: [ (string | {v, t?, h?})[] ] }
--
--  Rows are cells, not typed records, because these tables do not share a
--  schema - one is Manager/Year/PF, the next is Winner/W/Loser/L/Margin. `t`
--  is a display tone (rank | good | bad | accent | info) and `h` a hover hint,
--  both carried over from the source page so the numbers keep their meaning.
--
--  Column counts are asserted at generation time, not here: a ragged row is a
--  scraping bug, and it should fail on the machine that scraped it.
-- ============================================================================

with target as (
  select l.id from public.leagues l
  -- where l.name = 'CoolClan'      -- uncomment and set if you have several
  order by l.created_at
  limit 1
)
insert into public.league_history (league_id, kind, payload)
